//! Involute gears in the transverse plane: external teeth generated by a rack cutter (so the
//! root fillet is the true trochoid and undercut comes out as it would on a hobbing machine),
//! internal teeth, and racks.

use std::f64::consts::{PI, TAU};

use crate::geom::{Outline, Seg, V2, inv, inv_inv};

/// The basic rack: tooth proportions in multiples of the normal module.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct BasicRack {
    /// Addendum coefficient ha* (1.0 full depth, 0.8 stub).
    pub addendum: f64,
    /// Dedendum coefficient hf* = ha* + c* (1.25 for ISO 53 profile A/B).
    pub dedendum: f64,
    /// Root (cutter tip) radius coefficient ρf* (0.38 for ISO 53 A).
    pub root_radius: f64,
}

impl Default for BasicRack {
    fn default() -> Self {
        Self { addendum: 1.0, dedendum: 1.25, root_radius: 0.38 }
    }
}

impl BasicRack {
    /// ISO 53 profiles, AGMA full depth and stub: (name, rack).
    pub const STANDARDS: &'static [(&'static str, BasicRack)] = &[
        ("iso53_a", BasicRack { addendum: 1.0, dedendum: 1.25, root_radius: 0.38 }),
        ("iso53_b", BasicRack { addendum: 1.0, dedendum: 1.25, root_radius: 0.3 }),
        ("iso53_c", BasicRack { addendum: 1.0, dedendum: 1.25, root_radius: 0.25 }),
        ("iso53_d", BasicRack { addendum: 1.0, dedendum: 1.4, root_radius: 0.39 }),
        ("agma_full_depth", BasicRack { addendum: 1.0, dedendum: 1.25, root_radius: 0.3 }),
        ("stub", BasicRack { addendum: 0.8, dedendum: 1.0, root_radius: 0.3 }),
        // For FDM printing: a little more root clearance so tips never bottom in a rough root,
        // and the largest root fillet the cutter allows (stronger, prints cleaner).
        ("print_fdm", BasicRack { addendum: 1.0, dedendum: 1.3, root_radius: 0.38 }),
    ];
    pub fn standard(name: &str) -> Option<BasicRack> {
        Self::STANDARDS.iter().find(|(n, _)| *n == name).map(|(_, r)| *r)
    }
}

/// An involute gear's tooth data in the transverse plane.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Involute {
    /// Tooth count (positive).
    pub teeth: u32,
    /// Normal module mn (mm).
    pub module: f64,
    /// Normal pressure angle αn (radians).
    pub pressure_angle: f64,
    /// Helix angle β at the pitch circle (radians, 0 for spur; the sign is the hand).
    pub helix: f64,
    /// Profile shift coefficient x (shift = x·mn, positive away from the centre).
    pub shift: f64,
    pub rack: BasicRack,
    /// Circular backlash at the pitch circle (mm): the tooth is thinner by this much.
    pub backlash: f64,
    /// Tip shortening (mm off the tip radius), for example to keep tip clearance after shifting.
    pub tip_shortening: f64,
    /// A non-integer tooth count used for the geometry instead of `teeth` (a bevel gear's
    /// virtual spur gear); 0 for none.
    pub virtual_teeth: f64,
}

impl Default for Involute {
    fn default() -> Self {
        Self {
            teeth: 20,
            module: 2.0,
            pressure_angle: 20f64.to_radians(),
            helix: 0.0,
            shift: 0.0,
            rack: BasicRack::default(),
            backlash: 0.0,
            tip_shortening: 0.0,
            virtual_teeth: 0.0,
        }
    }
}

impl Involute {
    pub fn z(&self) -> f64 {
        if self.virtual_teeth > 0.0 { self.virtual_teeth } else { f64::from(self.teeth) }
    }
    /// Transverse module mt = mn / cos β.
    pub fn mt(&self) -> f64 {
        self.module / self.helix.cos()
    }
    /// Transverse pressure angle αt.
    pub fn alpha_t(&self) -> f64 {
        (self.pressure_angle.tan() / self.helix.cos()).atan()
    }
    /// Pitch (reference) radius.
    pub fn r(&self) -> f64 {
        self.mt() * self.z() / 2.0
    }
    /// Base radius.
    pub fn rb(&self) -> f64 {
        self.r() * self.alpha_t().cos()
    }
    /// External tip radius.
    pub fn ra(&self) -> f64 {
        self.r() + (self.rack.addendum + self.shift) * self.module - self.tip_shortening
    }
    /// External root radius.
    pub fn rf(&self) -> f64 {
        self.r() - (self.rack.dedendum - self.shift) * self.module
    }
    /// Transverse tooth thickness on the pitch circle (arc length).
    pub fn thickness(&self) -> f64 {
        PI * self.mt() / 2.0 + 2.0 * self.shift * self.module * self.alpha_t().tan() - self.backlash
    }
    /// Half the tooth's angular thickness at radius `rr` (on the involute; radians).
    pub fn half_angle_at(&self, rr: f64) -> f64 {
        let r = self.r();
        let rb = self.rb();
        let at = self.alpha_t();
        let ar = (rb / rr.max(rb)).clamp(-1.0, 1.0).acos();
        self.thickness() / (2.0 * r) + inv(at) - inv(ar)
    }
    /// The tooth's transverse thickness (arc) at radius `rr`.
    pub fn thickness_at(&self, rr: f64) -> f64 {
        2.0 * rr * self.half_angle_at(rr)
    }
    /// Smallest tooth count without undercut for this rack and shift.
    pub fn min_teeth_no_undercut(&self) -> f64 {
        2.0 * (self.rack.addendum - self.shift) * self.helix.cos() / self.alpha_t().sin().powi(2)
    }
    /// The radius below which the involute is cut away (undercut), or None.
    pub fn undercut(&self) -> bool {
        // The rack's straight flank ends at ha*·mn below the pitch line (shifted); undercut when
        // that point lies past the interference point on the line of action.
        let reach = (self.rack.addendum - self.shift) * self.module;
        reach > self.r() * self.alpha_t().sin().powi(2) + 1e-9
    }
    /// The tip radius at which the tooth becomes pointed.
    pub fn pointed_radius(&self) -> f64 {
        let v = self.thickness() / (2.0 * self.r()) + inv(self.alpha_t());
        self.rb() / inv_inv(v).cos()
    }
    /// The base pitch (transverse).
    pub fn base_pitch(&self) -> f64 {
        PI * self.mt() * self.alpha_t().cos()
    }
    /// Span (base tangent) measurement over k teeth, with the k whose anvils touch the flanks
    /// nearest mid height (the usual tables' rule; for a shifted gear that is the circle through
    /// r + x·mn, so k grows with the shift).
    pub fn span(&self) -> (u32, f64) {
        let an = self.pressure_angle;
        let at = self.alpha_t();
        let z = self.z();
        let (sb, cb) = self.helix.sin_cos();
        let f = self.shift / z;
        let q = cb * cb + an.tan().powi(2);
        let reach = (q * (1.0 / cb + 2.0 * f).powi(2) - 1.0).max(0.0).sqrt();
        let ideal = z / PI * ((1.0 + sb * sb / q) * reach - inv(at) - 2.0 * f * an.tan()) + 0.5;
        let k = if ideal.is_finite() { ideal.round().clamp(1.0, (z - 1.0).max(1.0)) } else { 1.0 };
        let w = self.module * an.cos() * (PI * (k - 0.5) + z * inv(at)) + 2.0 * self.shift * self.module * an.sin()
            - self.backlash * an.cos() * self.helix.cos();
        (k as u32, w)
    }
    /// Measurement over two pins (balls for helical) of diameter `dp`; returns (M, pin diameter).
    pub fn over_pins(&self, dp: Option<f64>) -> (f64, f64) {
        let dp = dp.unwrap_or(1.728 * self.module);
        let at = self.alpha_t();
        let z = self.z();
        // Involute angle where the pin centre lies (ISO 21771, transverse).
        let v = self.thickness() / (2.0 * self.r()) + inv(at) + dp / (self.module * z * self.pressure_angle.cos()) - PI / z;
        let am = inv_inv(v);
        let rm = self.rb() / am.cos();
        let m = if self.teeth.is_multiple_of(2) { 2.0 * rm + dp } else { 2.0 * rm * (PI / (2.0 * z)).cos() + dp };
        (m, dp)
    }
}

/// A rack cutter point and its outward normal (pointing from the cutter into the gear).
struct CutterPt {
    u: f64,
    v: f64,
    nu: f64,
    nv: f64,
}

/// The rack cutter generating the right side of the tooth space centred on +y, in the
/// transverse plane: its tip flat (cuts the root), tip fillet (cuts the trochoid) and straight
/// flank (cuts the involute), each a curve with a parameter from 0 to 1.
struct Cutter {
    r: f64,
    datum: f64,
    hc: f64,
    uc: f64,
    vc: f64,
    rho: f64,
    fillet_end: f64,
    tan_at: f64,
    normal: (f64, f64),
    flank_start: (f64, f64),
    v_top: f64,
}

/// Coarse samples per cutter curve (tip flat, fillet, flank), refined where a radius is wanted.
const CUTTER_SAMPLES: [usize; 3] = [8, 60, 120];

impl Cutter {
    fn new(g: &Involute) -> Self {
        let mn = g.module;
        let at = g.alpha_t();
        let r = g.r();
        let pt = PI * g.mt();
        let hc = g.rack.dedendum * mn;
        // Fillet: tangent to the tip line and the flank; no bigger than the tip allows.
        let u_tip_corner = pt / 4.0 - hc * at.tan();
        // Largest radius whose centre still sits right of the tooth middle (full round tip).
        let rho_max = (u_tip_corner.max(0.0)) / (1.0 / at.cos() - at.tan()).max(1e-9);
        let rho = (g.rack.root_radius * mn).min(rho_max * 0.999).max(1e-7);
        let vc = -hc + rho;
        let uc = pt / 4.0 + vc * at.tan() - rho / at.cos();
        let normal = (at.cos(), -at.sin());
        Cutter {
            r,
            datum: r + g.shift * mn,
            hc,
            uc,
            vc,
            rho,
            fillet_end: normal.1.atan2(normal.0),
            tan_at: at.tan(),
            normal,
            flank_start: (uc + rho * normal.0, vc + rho * normal.1),
            v_top: (g.rack.addendum + g.rack.dedendum) * mn,
        }
    }
    /// The cutter point at `t` along curve `k` (0 tip flat, 1 fillet, 2 flank).
    fn point(&self, k: usize, t: f64) -> CutterPt {
        match k {
            0 => CutterPt { u: self.uc.max(0.0) * t, v: -self.hc, nu: 0.0, nv: -1.0 },
            1 => {
                // From straight down (−π/2) round to the flank's normal.
                let a = -PI / 2.0 + (self.fillet_end + PI / 2.0) * t;
                let (s, c) = a.sin_cos();
                CutterPt { u: self.uc + self.rho * c, v: self.vc + self.rho * s, nu: c, nv: s }
            }
            _ => {
                let (fu, fv) = self.flank_start;
                let v = fv + (self.v_top - fv) * t;
                CutterPt { u: fu + (v - fv) * self.tan_at, v, nu: self.normal.0, nv: self.normal.1 }
            }
        }
    }
    /// The gear point the cutter point at `t` along curve `k` cuts: where its normal passes
    /// through the pitch point as the rack rolls on the pitch circle.
    fn gear(&self, k: usize, t: f64) -> V2 {
        let c = self.point(k, t);
        let y = self.datum + c.v;
        let s = if c.nv.abs() > 1e-12 { (y - self.r) * c.nu / c.nv - c.u } else { -c.u };
        V2::new(c.u + s, y).rot(s / self.r)
    }
}

/// The curves the cutter generates for the right side of the tooth space centred on +y, as
/// coarse samples of gear points, and the cutter to refine them with.
struct Generated {
    cutter: Cutter,
    curves: [Vec<V2>; 3],
    /// The samples' distances from the centre.
    radii: [Vec<f64>; 3],
}

impl Generated {
    fn new(g: &Involute) -> Self {
        let cutter = Cutter::new(g);
        let curves: [Vec<V2>; 3] = [0, 1, 2].map(|k| (0..=CUTTER_SAMPLES[k]).map(|i| cutter.gear(k, i as f64 / CUTTER_SAMPLES[k] as f64)).collect());
        let radii = [0, 1, 2].map(|k| curves[k].iter().map(|q| q.len()).collect());
        Generated { cutter, curves, radii }
    }
    /// The space's half angle at radius `rr`: the largest angle any generated curve reaches
    /// there (each crossing refined on the cutter itself), and which curve (0 tip, 1 fillet,
    /// 2 flank).
    fn space_half(&self, rr: f64) -> Option<(f64, usize)> {
        let mut best: Option<(f64, usize)> = None;
        for (k, c) in self.curves.iter().enumerate() {
            let n = c.len() - 1;
            let radii = &self.radii[k];
            for i in 0..n {
                let (ra, rb) = (radii[i], radii[i + 1]);
                if (ra - rr) * (rb - rr) > 0.0 || (ra - rb).abs() <= 1e-12 * rr {
                    continue;
                }
                let up = rb > ra;
                let (mut lo, mut hi) = (i as f64 / n as f64, (i + 1) as f64 / n as f64);
                let mut p = c[i];
                for _ in 0..48 {
                    let mid = 0.5 * (lo + hi);
                    p = self.cutter.gear(k, mid);
                    if (p.len() < rr) == up {
                        lo = mid;
                    } else {
                        hi = mid;
                    }
                    if hi - lo < 1e-15 {
                        break;
                    }
                }
                let a = psi(p);
                if best.is_none_or(|(b, _)| a > b) {
                    best = Some((a, k));
                }
            }
        }
        best
    }
}

/// The angle from +y towards +x (clockwise), for the tooth space centred on +y.
fn psi(p: V2) -> f64 {
    p.x.atan2(p.y)
}

/// The most a working flank's fit point spline may stray from the exact curve, in modules
/// (0.6 µm per mm of module; root fillets, which nothing runs on, get [`FILLET_TOLERANCE`]).
pub const PROFILE_TOLERANCE: f64 = 6e-4;
/// The most a root fillet's spline may stray from the generated trochoid, in modules.
pub const FILLET_TOLERANCE: f64 = 2e-3;

/// A generated external tooth: its flank (from the root up) as the tooth's half angle against
/// radius, split where the fillet meets the involute.
#[derive(Clone, Debug, PartialEq)]
pub struct ToothFlank {
    /// Root radius, tip radius actually used (lowered when the tooth would be pointed).
    pub rf: f64,
    pub ra: f64,
    /// Half angles of the tooth at the root and the tip.
    pub root_half: f64,
    pub tip_half: f64,
    /// (radius, half angle) from the root to where the fillet ends.
    pub fillet: Vec<(f64, f64)>,
    /// (radius, half angle) from there to the tip.
    pub flank: Vec<(f64, f64)>,
    /// The flank is cut away near its base (undercut).
    pub undercut: bool,
    /// The tooth came to a point before its tip radius.
    pub pointed: bool,
}

impl ToothFlank {
    /// What makes these teeth unbuildable, if anything.
    pub fn defect(&self) -> Option<&'static str> {
        let finite = [self.rf, self.ra, self.root_half, self.tip_half].iter().all(|v| v.is_finite())
            && self.fillet.iter().chain(&self.flank).all(|(r, h)| r.is_finite() && h.is_finite());
        if !finite {
            return Some("the tooth geometry doesn't work out (check the inputs)");
        }
        if self.rf <= 0.0 {
            return Some("the root circle reaches the centre");
        }
        if self.ra <= self.rf || self.fillet.len() + self.flank.len() < 2 || self.root_half * self.rf <= 0.0 {
            return Some("no tooth is left between the root and tip circles");
        }
        if self.pointed && self.flank.len() < 2 {
            return Some("the undercut cuts through the teeth");
        }
        None
    }
}

/// Bisection for the boundary of `inside` between `lo` (inside) and `hi` (not): the last
/// inside value found.
fn boundary(mut lo: f64, mut hi: f64, inside: &dyn Fn(f64) -> bool) -> f64 {
    for _ in 0..60 {
        let mid = 0.5 * (lo + hi);
        if inside(mid) {
            lo = mid;
        } else {
            hi = mid;
        }
    }
    lo
}

/// Fit points (radius, half angle) along `half` from `r0` to `r1` by `grade`, or none when the
/// side is too short to be a curve of its own (under `min_gap` end to end).
pub(crate) fn side_points(half: &dyn Fn(f64) -> f64, grade: &dyn Fn(f64) -> f64, tol: f64, min_gap: f64) -> Vec<(f64, f64)> {
    let (a, b) = (grade(0.0), grade(1.0));
    let length = V2::polar(a, half(a)).dist(V2::polar(b, half(b)));
    if !(length > 2.0 * min_gap) {
        return Vec::new();
    }
    let pts = crate::geom::fit_profile(half, grade, tol, 3, 24);
    // Drop points that crowd the previous one (the last point stays).
    let mut out: Vec<(f64, f64)> = Vec::with_capacity(pts.len());
    for (i, p) in pts.iter().enumerate() {
        let q = V2::polar(p.0, p.1);
        let last = i + 1 == pts.len();
        if let Some(prev) = out.last()
            && q.dist(V2::polar(prev.0, prev.1)) < min_gap
        {
            if last {
                let l = out.len() - 1;
                if l > 0 {
                    out[l] = *p;
                }
            }
            continue;
        }
        out.push(*p);
    }
    if out.len() < 2 {
        return Vec::new();
    }
    out
}

/// The generated external tooth's half angle against radius (root fillet and flank alike),
/// each crossing refined on the cutter itself: for measuring the tooth (root thickness, fillet
/// curvature).
pub fn tooth_half_sampler(g: &Involute) -> impl Fn(f64) -> Option<f64> {
    let cut = Generated::new(g);
    let z = g.z();
    let backlash_turn = g.backlash / (2.0 * g.r());
    move |rr: f64| cut.space_half(rr).map(|(s, _)| PI / z - s - backlash_turn)
}

/// Generates the flank of an external involute tooth with its trochoidal root fillet: the
/// fillet as the cutter's tip generates it, the flank above it as the exact involute, each as
/// few fit points as keep the sketch's spline within [`PROFILE_TOLERANCE`] of it.
pub fn external_flank(g: &Involute) -> ToothFlank {
    let cut = Generated::new(g);
    let z = g.z();
    let r = g.r();
    let rf = g.rf();
    let m = g.module;
    let backlash_turn = g.backlash / (2.0 * r);
    let half = |rr: f64| -> Option<(f64, usize)> { cut.space_half(rr).map(|(s, k)| (PI / z - s - backlash_turn, k)) };
    // The root: the tip flat's last point.
    let root_half = PI / z - psi(*cut.curves[0].last().unwrap_or(&V2::new(0.0, rf))) - backlash_turn;
    let ra_full = g.ra();
    // Up from the root: where the generated involute takes over from the fillet, and where the
    // tooth runs out of thickness (a pointed tip, lowered to keep a sliver of land, or an
    // undercut neck).
    let land = 0.02 * m;
    let thick = |rr: f64| half(rr).is_some_and(|(h, _)| h * rr > land / 2.0);
    let mut ra = ra_full;
    let mut pointed = false;
    let mut handover: Option<f64> = None;
    let probes = 200;
    let mut prev = rf;
    if ra_full > rf {
        for i in 1..=probes {
            let rr = rf + (ra_full - rf) * (i as f64 / probes as f64) * (1.0 - 1e-12);
            let Some((h, k)) = half(rr) else {
                prev = rr;
                continue;
            };
            if handover.is_none() && k == 2 {
                handover = Some(boundary(rr, prev, &|x| half(x).is_some_and(|(_, k)| k == 2)));
            }
            if h * rr <= land / 2.0 {
                ra = boundary(prev, rr, &thick);
                pointed = true;
                break;
            }
            prev = rr;
        }
    }
    let handover = handover.filter(|h| *h < ra).unwrap_or(ra);
    let tol = PROFILE_TOLERANCE * m;
    let min_gap = 5e-6 * ra.abs().max(m);
    let rb = g.rb();
    let involute = |rr: f64| g.half_angle_at(rr);
    let has_flank = handover < ra;
    let fillet_half = |rr: f64| -> f64 {
        if rr <= rf {
            root_half
        } else if rr >= handover && has_flank {
            involute(handover)
        } else {
            half(rr).map(|x| x.0).unwrap_or(root_half)
        }
    };
    // Bunched towards the root, where the fillet runs nearly round the root circle.
    let span = handover - rf;
    let mut fillet = if span > 0.0 {
        side_points(&fillet_half, &|s| if s >= 1.0 { handover } else { rf + span * s * s }, FILLET_TOLERANCE * m, min_gap)
    } else {
        Vec::new()
    };
    // The involute by its roll angle (the points crowd towards the base circle, where it
    // bends most).
    let t_of = |rr: f64| ((rr / rb).powi(2) - 1.0).max(0.0).sqrt();
    let (t0, t1) = (t_of(handover), t_of(ra));
    let grade = |s: f64| -> f64 {
        if s <= 0.0 {
            handover
        } else if s >= 1.0 {
            ra
        } else {
            let t = t0 + (t1 - t0) * s;
            (rb * (1.0 + t * t).sqrt()).clamp(handover, ra)
        }
    };
    let flank = if has_flank { side_points(&involute, &grade, tol, min_gap) } else { Vec::new() };
    if let (Some(a), Some(b)) = (fillet.last_mut(), flank.first()) {
        *a = *b;
    }
    let tip_half = flank.last().or(fillet.last()).map(|p| p.1).unwrap_or(root_half);
    ToothFlank { rf, ra, root_half: root_half.max(0.0), tip_half, fillet, flank, undercut: g.undercut(), pointed }
}

/// Teeth placed round the centre, tooth 0 centred at `phase` (radians from +x).
pub fn external_outline(g: &Involute, phase: f64) -> (Outline, ToothFlank) {
    let f = external_flank(g);
    (teeth_outline(&f, g.teeth, phase), f)
}

/// The closed outline of `n` teeth with flank `f`, counter-clockwise.
pub fn teeth_outline(f: &ToothFlank, n: u32, phase: f64) -> Outline {
    let pitch = TAU / f64::from(n);
    let mut segs = Vec::new();
    // One tooth centred on +x: up its clockwise side (negative angles), across the tip, down the
    // other side, then the root arc to the next tooth.
    let side = |pts: &[(f64, f64)], sign: f64| -> Vec<V2> { pts.iter().map(|(rr, h)| V2::polar(*rr, sign * h)).collect() };
    let lower_fillet = side(&f.fillet, -1.0);
    let lower_flank = side(&f.flank, -1.0);
    let upper_flank: Vec<V2> = side(&f.flank, 1.0).into_iter().rev().collect();
    let upper_fillet: Vec<V2> = side(&f.fillet, 1.0).into_iter().rev().collect();
    let root_gap = pitch - 2.0 * f.root_half;
    for k in 0..n {
        let a = phase + pitch * f64::from(k);
        let rot = |p: &Vec<V2>| -> Vec<V2> { p.iter().map(|q| q.rot(a)).collect() };
        let start = V2::polar(f.rf, a - f.root_half);
        let mut lf = rot(&lower_fillet);
        let lf_len = lf.len();
        if lf.len() >= 2 {
            lf[0] = start;
            segs.push(Seg::Spline(lf));
        }
        if lower_flank.len() >= 2 {
            let mut lo = rot(&lower_flank);
            // No fillet: the flank itself starts on the root circle, so the root arc on either
            // side is a true arc (the sampled flank can end a hair off it).
            if lf_len < 2 && lo[0].dist(start) < 1e-4 * f.rf.max(1.0) {
                lo[0] = start;
            }
            segs.push(Seg::Spline(lo));
        }
        let (ta, tb) = (V2::polar(f.ra, a - f.tip_half), V2::polar(f.ra, a + f.tip_half));
        // Rounded tip corners ([`shape_tips`]): the flank stops short of the tip circle and an
        // arc, tangent to the tip circle where the land starts, joins the two.
        let round = lower_flank.last().and_then(|q| tip_round_centre(q.rot(a), ta));
        if let (Some(c), Some(q)) = (round, lower_flank.last()) {
            segs.push(Seg::Arc { c, a: q.rot(a), b: ta, ccw: true });
        }
        if f.tip_half > 1e-9 {
            segs.push(Seg::Arc { c: V2::ZERO, a: ta, b: tb, ccw: true });
        }
        if let (Some(_), Some(q)) = (round, upper_flank.first())
            && let Some(c) = tip_round_centre(q.rot(a), tb)
        {
            segs.push(Seg::Arc { c, a: tb, b: q.rot(a), ccw: true });
        }
        let mut uf = rot(&upper_fillet);
        let end = V2::polar(f.rf, a + f.root_half);
        if upper_flank.len() >= 2 {
            let mut up = rot(&upper_flank);
            let l = up.len() - 1;
            if uf.len() < 2 && up[l].dist(end) < 1e-4 * f.rf.max(1.0) {
                up[l] = end;
            }
            segs.push(Seg::Spline(up));
        }
        if uf.len() >= 2 {
            let l = uf.len() - 1;
            uf[l] = end;
            segs.push(Seg::Spline(uf));
        }
        if root_gap > 1e-6 {
            segs.push(Seg::Arc { c: V2::ZERO, a: end, b: V2::polar(f.rf, a + pitch - f.root_half), ccw: true });
        }
    }
    join_ends(&mut segs);
    Outline { segs }
}

/// A tooth whose two sides differ (a spiral bevel's on a flat section, a throated worm wheel's
/// off its mid plane): each side from the root circle up to the tip circle as one or more
/// splines' fit points, (radius, angle from the tooth's centre line). The lower side is the
/// clockwise one. Every side of every tooth has the same pieces, so outlines made from sides
/// with the same piece and point counts correspond segment for segment (a loft's sections).
#[derive(Clone, Debug, PartialEq)]
pub struct ToothSides {
    pub rf: f64,
    pub ra: f64,
    pub lower: Vec<Vec<(f64, f64)>>,
    pub upper: Vec<Vec<(f64, f64)>>,
}

/// The closed outline of `n` teeth with sides `t`, counter-clockwise, tooth 0's centre line at
/// `phase`.
pub fn sided_outline(t: &ToothSides, n: u32, phase: f64) -> Outline {
    let pitch = TAU / f64::from(n);
    let mut segs = Vec::new();
    let end_of = |side: &Vec<Vec<(f64, f64)>>, tip: bool| -> (f64, f64) {
        let piece = if tip { side.last() } else { side.first() };
        piece.and_then(|p| if tip { p.last() } else { p.first() }).copied().unwrap_or((if tip { t.ra } else { t.rf }, 0.0))
    };
    for k in 0..n {
        let a = phase + pitch * f64::from(k);
        let at = |q: &(f64, f64)| V2::polar(q.0, a + q.1);
        for piece in &t.lower {
            segs.push(Seg::Spline(piece.iter().map(at).collect()));
        }
        let (lo, hi) = (end_of(&t.lower, true), end_of(&t.upper, true));
        if (hi.1 - lo.1) * t.ra > 1e-9 {
            segs.push(Seg::Arc { c: V2::ZERO, a: V2::polar(t.ra, a + lo.1), b: V2::polar(t.ra, a + hi.1), ccw: true });
        }
        for piece in t.upper.iter().rev() {
            segs.push(Seg::Spline(piece.iter().rev().map(at).collect()));
        }
        let (from, to) = (end_of(&t.upper, false), end_of(&t.lower, false));
        if (pitch + to.1 - from.1) * t.rf > 1e-9 {
            segs.push(Seg::Arc { c: V2::ZERO, a: V2::polar(t.rf, a + from.1), b: V2::polar(t.rf, a + pitch + to.1), ccw: true });
        }
    }
    join_ends(&mut segs);
    Outline { segs }
}

/// The centre of the arc that rounds a tip corner: through the flank's end `p`, tangent to the
/// tip circle at `t`. None when the flank runs up to the tip circle (no rounding).
fn tip_round_centre(p: V2, t: V2) -> Option<V2> {
    let ra = t.len();
    if !(p.len() < ra * (1.0 - 1e-7)) {
        return None;
    }
    let out = t.norm();
    let d = t - p;
    let along = d.dot(out);
    if !(along > 0.0) {
        return None;
    }
    let rho = d.dot(d) / (2.0 * along);
    (rho.is_finite() && rho > 0.0 && rho < ra).then(|| t - out * rho)
}

impl ToothFlank {
    /// The same tooth with each side turned `d` radians towards its middle (thinner by 2·d of
    /// angle at every radius): piece for piece the same outline, for lofting between the two.
    pub fn thinned(&self, d: f64) -> ToothFlank {
        let side = |pts: &[(f64, f64)]| -> Vec<(f64, f64)> { pts.iter().map(|(r, h)| (*r, h - d)).collect() };
        ToothFlank {
            root_half: self.root_half - d,
            tip_half: self.tip_half - d,
            fillet: side(&self.fillet),
            flank: side(&self.flank),
            ..self.clone()
        }
    }
}

/// Tip relief and tip rounding on a generated external tooth (`f` from [`external_flank`] of
/// `g`), by refitting its flank.
///
/// - Tip relief: over the top `relief_height` (mm of radius) the flank falls away from the
///   involute, linearly with radius, to `relief` (mm, normal to the flank) at the tip, so a tooth
///   deflected under load (or printed a little fat) comes into mesh gently.
/// - Tip rounding: each tip corner becomes an arc of radius `round` (mm), tangent to the flank
///   and to the tip circle. The flank then ends below the tip circle and `tip_half` is where the
///   land starts; [`teeth_outline`] draws the arcs.
///
/// Returns the rounding radius used: less than asked when the tooth is too thin or too short for
/// it (0 when there is none).
pub fn shape_tips(f: &mut ToothFlank, g: &Involute, relief: f64, relief_height: f64, round: f64) -> f64 {
    if f.pointed || f.flank.len() < 2 || !(relief > 0.0 || round > 0.0) {
        return 0.0;
    }
    let m = g.module;
    let (rb, ra, r0) = (g.rb(), f.ra, f.flank[0].0);
    if !(ra > r0 && rb > 0.0 && ra.is_finite()) {
        return 0.0;
    }
    // The least land left at the tip (as the flank generator keeps).
    let land = 0.01 * m / ra;
    let rs = (ra - relief_height.max(0.0)).max(r0);
    let mut k = if relief > 0.0 && ra > rs { relief / rb / (ra - rs) } else { 0.0 };
    let full = g.half_angle_at(ra);
    if k > 0.0 && full - k * (ra - rs) < land {
        k = ((full - land) / (ra - rs)).max(0.0);
    }
    let half = |rr: f64| g.half_angle_at(rr) - k * (rr - rs).max(0.0);
    let (mut end, mut tip_half, mut used) = (ra, half(ra), 0.0);
    let mut rho = round.min(0.45 * (ra - r0));
    while rho >= 0.01 * m {
        let rc = ra - rho;
        // From a centre at angle `tc` to the flank: (distance, the nearest flank point's radius).
        let reach = |tc: f64| -> (f64, f64) {
            let c = V2::polar(rc, tc);
            let d = |rr: f64| V2::polar(rr, half(rr)).dist(c);
            let lo = (ra - 3.0 * rho).max(r0);
            let n = 32;
            let step = (ra - lo) / n as f64;
            let mut best = (f64::INFINITY, lo);
            for i in 0..=n {
                let rr = lo + step * i as f64;
                let v = d(rr);
                if v < best.0 {
                    best = (v, rr);
                }
            }
            let (mut a, mut b) = ((best.1 - step).max(lo), (best.1 + step).min(ra));
            for _ in 0..40 {
                let (x1, x2) = (a + (b - a) / 3.0, b - (b - a) / 3.0);
                if d(x1) < d(x2) { b = x2 } else { a = x1 }
            }
            let rr = 0.5 * (a + b);
            (d(rr), rr)
        };
        // The centre sits on the flank at `half(rc)` and moves away from it towards the tooth's
        // middle: the angle at which it is one radius from the flank.
        let on_flank = half(rc);
        if on_flank > land && reach(land).0 >= rho {
            let (mut a, mut b) = (land, on_flank);
            for _ in 0..50 {
                let mid = 0.5 * (a + b);
                if reach(mid).0 >= rho { a = mid } else { b = mid }
            }
            let rt = reach(a).1;
            if rt > r0 + 0.05 * (ra - r0) && rt < ra * (1.0 - 1e-6) {
                (end, tip_half, used) = (rt, a, rho);
                break;
            }
        }
        rho *= 0.8;
    }
    if used == 0.0 && k == 0.0 {
        return 0.0;
    }
    let t_of = |rr: f64| ((rr / rb).powi(2) - 1.0).max(0.0).sqrt();
    let (t0, t1) = (t_of(r0), t_of(end));
    let grade = |s: f64| -> f64 {
        if s <= 0.0 {
            r0
        } else if s >= 1.0 {
            end
        } else {
            let t = t0 + (t1 - t0) * s;
            (rb * (1.0 + t * t).sqrt()).clamp(r0, end)
        }
    };
    let pts = side_points(&half, &grade, PROFILE_TOLERANCE * m, 5e-6 * ra.abs().max(m));
    if pts.len() < 2 {
        return 0.0;
    }
    f.flank = pts;
    f.tip_half = tip_half;
    used
}

/// Snap each segment's start onto the previous one's end (sampling leaves tiny gaps).
pub(crate) fn join_ends(segs: &mut [Seg]) {
    let n = segs.len();
    for i in 0..n {
        let prev_end = segs[(i + n - 1) % n].end();
        match &mut segs[i] {
            Seg::Line(a, _) => *a = prev_end,
            Seg::Arc { a, .. } => *a = prev_end,
            Seg::Spline(p) => p[0] = prev_end,
            Seg::Circle(..) => {}
        }
    }
}

/// An internal (ring) gear's teeth: the tooth spaces are involute "teeth" pointing outwards.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Internal {
    pub gear: Involute,
}

impl Internal {
    /// Internal tip radius (the teeth's inner ends): the basic rack's addendum, but no deeper
    /// than a rack-cut pinion has involute for. A ring's tip reaches further down a pinion's
    /// flank than the rack that cut the pinion did, so a full addendum would dig into the
    /// pinion's root fillets; the limit here is for a pinion without undercut and with the
    /// ring's own shift (for 20° it comes to about 1 − 7.5 / z modules of addendum).
    pub fn r_tip(&self) -> f64 {
        let g = &self.gear;
        let at = g.alpha_t();
        let reach = (g.rack.addendum - g.shift) * g.module;
        let clear = g.rb().hypot((g.r() * at.sin() - reach / at.sin()).max(0.0));
        // (A tip circle that has no radius at all stays that way, for the plan to refuse.)
        let standard = g.r() - reach;
        if standard > 0.0 { standard.max(clear) + g.tip_shortening } else { standard + g.tip_shortening }
    }
    /// The smallest inner tip radius that stays on the involute of this pinion: `form_radius`
    /// where the pinion's involute starts (its flank's first radius), at `mesh`'s centre distance.
    pub fn r_tip_clear(&self, pinion: &Involute, form_radius: f64, mesh: &Mesh) -> f64 {
        let rb1 = pinion.rb();
        let along = (form_radius * form_radius - rb1 * rb1).max(0.0).sqrt();
        self.gear.rb().hypot(mesh.center_distance * mesh.working_pressure_angle.sin() + along)
    }
    /// Internal root radius (outer).
    pub fn r_root(&self) -> f64 {
        let g = &self.gear;
        g.r() + (g.rack.dedendum + g.shift) * g.module
    }
    /// Space width on the pitch circle (arc). A positive shift moves the teeth outwards, so the
    /// pitch circle meets them nearer their (inner) tips, where they are thinner: the space
    /// widens (ISO 21771; it is what makes `mesh_internal`'s working pressure angle hold).
    pub fn space(&self) -> f64 {
        let g = &self.gear;
        PI * g.mt() / 2.0 + 2.0 * g.shift * g.module * g.alpha_t().tan() + g.backlash
    }
    /// The space's half angle at radius `rr` (the involute, radial below the base circle).
    pub fn space_half_at(&self, rr: f64) -> f64 {
        let g = &self.gear;
        let rb = g.rb();
        let ar = (rb / rr.max(rb)).acos();
        self.space() / (2.0 * g.r()) + inv(g.alpha_t()) - inv(ar)
    }
    /// The tooth spaces as the teeth of a virtual external gear (its root on the ring's tip
    /// circle, its tip on the ring's root circle). Teeth that would come to a point at their
    /// inner tips have the tips raised to keep a land (`ra`… `rf` is then above `r_tip`);
    /// spaces that would close before the root circle have the root lowered (`pointed`).
    pub fn space_flank(&self) -> ToothFlank {
        let g = &self.gear;
        let m = g.module;
        let (mut r0, mut r1) = (self.r_tip(), self.r_root());
        let land = 0.02 * m;
        let pitch_half = PI / g.z();
        let space = |rr: f64| self.space_half_at(rr);
        let tooth_ok = |rr: f64| (pitch_half - space(rr)) * rr >= land / 2.0;
        let space_ok = |rr: f64| space(rr) * rr >= land / 2.0;
        let mut raised = false;
        if r0 > 0.0 && r1 > r0 && !tooth_ok(r0) && tooth_ok(r1) {
            r0 = boundary(r1, r0, &tooth_ok);
            raised = true;
        }
        let mut pointed = false;
        if r1 > r0 && r0 > 0.0 && !space_ok(r1) && space_ok(r0) {
            r1 = boundary(r0, r1, &space_ok);
            pointed = true;
        }
        let rb = g.rb();
        let tol = PROFILE_TOLERANCE * m;
        let min_gap = 5e-6 * r1.abs().max(m);
        let lo = r0.max(rb);
        let t_of = |rr: f64| ((rr / rb).powi(2) - 1.0).max(0.0).sqrt();
        let (t0, t1) = (t_of(lo), t_of(r1));
        let grade = |s: f64| -> f64 {
            if s <= 0.0 {
                lo
            } else if s >= 1.0 {
                r1
            } else {
                let t = t0 + (t1 - t0) * s;
                (rb * (1.0 + t * t).sqrt()).clamp(lo, r1)
            }
        };
        // Below the base circle the space's sides run straight in, radially.
        let radial = if r0 < lo && lo - r0 > min_gap { vec![(r0, space(r0)), (lo, space(lo))] } else { Vec::new() };
        let mut flank = if r1 > lo { side_points(&space, &grade, tol, min_gap) } else { Vec::new() };
        if flank.is_empty() && radial.is_empty() && r1 > r0 {
            flank = vec![(r0, space(r0)), (r1, space(r1))];
        }
        let _ = raised;
        ToothFlank { rf: r0, ra: r1, root_half: space(r0), tip_half: space(r1).max(0.0), fillet: radial, flank, undercut: false, pointed }
    }
    /// The toothed boundary, counter-clockwise; tooth 0 (material) centred at `phase`.
    pub fn outline(&self, phase: f64, root_fillet: f64) -> Outline {
        let _ = root_fillet;
        teeth_outline(&self.space_flank(), self.gear.teeth, phase + PI / self.gear.z())
    }
}

/// A straight-toothed rack's outline in the plane: teeth along +x, pitch line at y = 0, teeth
/// pointing +y, from x = 0 for `count` teeth, body down to y = −`depth_below`.
pub fn rack_outline(g: &Involute, count: u32, depth_below: f64) -> Outline {
    let p = PI * g.mt();
    let at = g.alpha_t();
    let ha = (g.rack.addendum + g.shift) * g.module - g.tip_shortening;
    let hf = (g.rack.dedendum - g.shift) * g.module;
    // Tooth thickness on the line y = 0. A shift moves the whole profile up by x·mn (tips and
    // roots with it), so the datum line, where tooth and space are equal, is at y = x·mn and the
    // tooth is thicker on y = 0.
    let s = p / 2.0 + 2.0 * g.shift * g.module * at.tan() - g.backlash;
    let half_tip = s / 2.0 - ha * at.tan();
    let half_root = s / 2.0 + hf * at.tan();
    let mut pts = vec![V2::new(0.0, -depth_below)];
    let x_end = p * f64::from(count);
    pts.push(V2::new(x_end, -depth_below));
    let mut top = Vec::new();
    for k in 0..count {
        let c = p * (f64::from(k) + 0.5);
        top.push(V2::new(c - half_root.min(p / 2.0), -hf));
        top.push(V2::new(c - half_tip.max(0.0), ha));
        top.push(V2::new(c + half_tip.max(0.0), ha));
        top.push(V2::new(c + half_root.min(p / 2.0), -hf));
    }
    pts.push(V2::new(x_end, -hf));
    pts.extend(top.into_iter().rev());
    pts.push(V2::new(0.0, -hf));
    let mut segs = Vec::new();
    let mut clean: Vec<V2> = Vec::new();
    for q in pts {
        if clean.last().is_none_or(|l: &V2| l.dist(q) > 1e-9) {
            clean.push(q);
        }
    }
    for i in 0..clean.len() {
        segs.push(Seg::Line(clean[i], clean[(i + 1) % clean.len()]));
    }
    Outline { segs }
}

/// Contact ratio and geometry of two external (or external with internal) involute gears in mesh.
#[derive(Clone, Copy, Debug, PartialEq, Default)]
pub struct Mesh {
    /// Working transverse pressure angle (radians).
    pub working_pressure_angle: f64,
    /// Reference (no shift) and working centre distance.
    pub center_distance_ref: f64,
    pub center_distance: f64,
    /// Transverse, overlap and total contact ratios.
    pub contact_ratio: f64,
    pub overlap_ratio: f64,
    pub total_contact_ratio: f64,
    /// Tip clearances at the two roots (mm).
    pub clearance_1: f64,
    pub clearance_2: f64,
    pub ratio: f64,
}

/// Mesh of two external gears (same module, pressure angle and opposite helix), `face` wide.
pub fn mesh_external(g1: &Involute, g2: &Involute, face: f64) -> Mesh {
    let at = g1.alpha_t();
    let (z1, z2) = (g1.z(), g2.z());
    let inv_w = 2.0 * g1.pressure_angle.tan() * (g1.shift + g2.shift) / (z1 + z2) + inv(at);
    let aw_t = inv_inv(inv_w);
    let a0 = g1.r() + g2.r();
    let aw = a0 * at.cos() / aw_t.cos();
    let (ra1, ra2) = (g1.ra(), g2.ra());
    let (rb1, rb2) = (g1.rb(), g2.rb());
    let ea = ((ra1 * ra1 - rb1 * rb1).max(0.0).sqrt() + (ra2 * ra2 - rb2 * rb2).max(0.0).sqrt() - aw * aw_t.sin()) / g1.base_pitch();
    let eb = face * g1.helix.abs().sin() / (PI * g1.module);
    Mesh {
        working_pressure_angle: aw_t,
        center_distance_ref: a0,
        center_distance: aw,
        contact_ratio: ea,
        overlap_ratio: eb,
        total_contact_ratio: ea + eb,
        clearance_1: aw - ra2 - g1.rf(),
        clearance_2: aw - ra1 - g2.rf(),
        ratio: z2 / z1,
    }
}

/// Mesh of an external pinion inside an internal gear.
pub fn mesh_internal(pinion: &Involute, ring: &Internal, face: f64) -> Mesh {
    let at = pinion.alpha_t();
    let (z1, z2) = (pinion.z(), ring.gear.z());
    let inv_w = 2.0 * pinion.pressure_angle.tan() * (ring.gear.shift - pinion.shift) / (z2 - z1) + inv(at);
    let aw_t = inv_inv(inv_w);
    let a0 = ring.gear.r() - pinion.r();
    let aw = a0 * at.cos() / aw_t.cos();
    let (ra1, ra2) = (pinion.ra(), ring.r_tip());
    let (rb1, rb2) = (pinion.rb(), ring.gear.rb());
    let ea = ((ra1 * ra1 - rb1 * rb1).max(0.0).sqrt() - (ra2 * ra2 - rb2 * rb2).max(0.0).sqrt() + aw * aw_t.sin()) / pinion.base_pitch();
    let eb = face * pinion.helix.abs().sin() / (PI * pinion.module);
    Mesh {
        working_pressure_angle: aw_t,
        center_distance_ref: a0,
        center_distance: aw,
        contact_ratio: ea,
        overlap_ratio: eb,
        total_contact_ratio: ea + eb,
        clearance_1: ring.r_root() - aw - ra1,
        clearance_2: ra2 - aw - pinion.rf(),
        ratio: z2 / z1,
    }
}

/// The total profile shift (x1 + x2) that brings two external gears to centre distance `aw`.
pub fn shift_sum_for_center(g1: &Involute, g2: &Involute, aw: f64) -> Option<f64> {
    let at = g1.alpha_t();
    let a0 = g1.r() + g2.r();
    let c = a0 * at.cos() / aw;
    if !(-1.0..=1.0).contains(&c) {
        return None;
    }
    let aw_t = c.acos();
    Some((inv(aw_t) - inv(at)) * (g1.z() + g2.z()) / (2.0 * g1.pressure_angle.tan()))
}

/// How gear 2 must be turned to mesh with gear 1: gear 1 at the origin with tooth 0 at `phase1`,
/// gear 2's centre in direction `dir` from it. External mesh. Returns gear 2's tooth-0 angle.
pub fn mesh_phase(z1: u32, phase1: f64, z2: u32, dir: f64) -> f64 {
    let (z1, z2) = (f64::from(z1), f64::from(z2));
    // A tooth of gear 1 on the line of centres (phase1 = dir) meets a space of gear 2 there.
    // Gear 1's tooth an angle d short of the line is an arc r1·d short of the pitch point; seen
    // from gear 2's centre, which faces the other way, the same arc is r1·d / r2 past it.
    dir + PI + PI / z2 + (z1 / z2) * (dir - phase1)
}

/// How an internal gear must be turned to mesh with a pinion inside it: the ring at the origin,
/// the pinion's centre in direction `dir` from it with its tooth 0 at `phase_pinion`. Returns the
/// ring's tooth-0 angle (see [`Internal::outline`]).
pub fn mesh_phase_internal(z_pinion: u32, phase_pinion: f64, z_ring: u32, dir: f64) -> f64 {
    let (zp, zr) = (f64::from(z_pinion), f64::from(z_ring));
    // Both turn the same way: the pinion's tooth an angle d past the line of centres sits in a
    // ring space d·zp / zr past it, and the ring's tooth is half a pitch on from its space.
    dir + (phase_pinion - dir) * zp / zr + PI / zr
}

/// The transverse contact ratio of an external pair counting only the involute that is really
/// there: from each gear's form radius (where its fillet or undercut ends, `flank[0]`) to its
/// actual tip. Undercut pinions lose the start of the path of contact, which [`mesh_external`]
/// does not see.
pub fn contact_ratio_external(g1: &Involute, f1: &ToothFlank, g2: &Involute, f2: &ToothFlank, mesh: &Mesh) -> f64 {
    let (rb1, rb2) = (g1.rb(), g2.rb());
    let along = |rr: f64, rb: f64| (rr * rr - rb * rb).max(0.0).sqrt();
    let form = |f: &ToothFlank| f.flank.first().map_or(f.rf, |p| p.0);
    // Along the line of action, from gear 1's base circle tangent point.
    let l = mesh.center_distance * mesh.working_pressure_angle.sin();
    let start = (l - along(f2.ra, rb2)).max(along(form(f1), rb1));
    let end = along(f1.ra, rb1).min(l - along(form(f2), rb2));
    (end - start) / g1.base_pitch()
}

/// Does the pinion's tip run into the ring's tip as the teeth come out of mesh (trochoid
/// interference: too few teeth between an internal gear and its pinion)? `ra1`: the pinion's tip
/// radius, at centre distance and working pressure angle of `mesh`.
pub fn internal_tip_interference(pinion: &Involute, ra1: f64, ring: &Internal, mesh: &Mesh) -> bool {
    let (a, aw) = (mesh.center_distance, mesh.working_pressure_angle);
    let ra2 = ring.r_tip();
    let (rb1, rb2) = (pinion.rb(), ring.gear.rb());
    if a <= 1e-9 || ra2 <= rb2 || ra1 <= rb1 {
        return ra2 < rb2;
    }
    let (aa1, aa2) = ((rb1 / ra1).acos(), (rb2 / ra2).acos());
    let th1 = ((ra2 * ra2 - ra1 * ra1 - a * a) / (2.0 * a * ra1)).clamp(-1.0, 1.0).acos() + inv(aa1) - inv(aw);
    let th2 = ((a * a + ra2 * ra2 - ra1 * ra1) / (2.0 * a * ra2)).clamp(-1.0, 1.0).acos();
    th1 * pinion.z() / ring.gear.z() + inv(aw) - inv(aa2) < th2
}
